        --primary-dark: #0f4bcc;
        --danger: #b42318;
        --success-bg: #ecfdf3;
        --success-text: #067647;
        --shadow-lg: 0 24px 60px -30px #10203333;
        --radius-xl: 28px;
        --radius-md: 16px;
      }

