        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #d9e8ff 0, transparent 28%),
          linear-gradient(180deg, #f8fbff 0%, var(--page-bg) 100%);
        color: var(--text-main);
      }

      a {
        color: inherit;
      }

      .skip-link {
        position: absolute;
        top: 1rem;
        left: 1rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 999px;
        background: var(--text-main);
        color: #fff;
        transform: translateY(-160%);
        transition: transform 0.2s ease;
      }

      .skip-link:focus {
        transform: translateY(0);
      }

      .page-shell {
        width: min(1100px, calc(100% - 2rem));
        margin: 0 auto;
        padding: 3rem 0 4rem;
      }

