        display: grid;
        grid-template-columns: minmax(0, 1fr) minmax(320px, 460px);
        gap: 2rem;
        align-items: stretch;
        min-width: 0;
      }

      .hero-copy,
      .form-card {
        background: var(--panel-bg);
        border: 1px solid var(--panel-muted);
        border-radius: var(--radius-xl);
        box-shadow: var(--shadow-lg);
      }

      .hero-copy {
        padding: 3rem;
        display: flex;
        flex-direction: column;
        justify-content: space-between;
        min-width: 0;
      }

      .eyebrow {
        display: inline-flex;
        align-items: center;
        width: fit-content;
        padding: 0.45rem 0.8rem;
        border-radius: 999px;
        background: #eef4ff;
        color: var(--primary-dark);
        font-weight: 700;
        letter-spacing: 0.01em;
      }

      h1 {
        margin: 1.25rem 0 1rem;
        font-size: clamp(2rem, 4vw, 3.4rem);
        line-height: 1.05;
      }

      .hero-copy p {
        max-width: 34rem;
        margin: 0;
        color: var(--text-muted);
        font-size: 1.05rem;
        line-height: 1.7;
      }

      .support-highlights {
        display: grid;
        grid-template-columns: repeat(3, minmax(0, 1fr));
        gap: 1rem;
        margin-top: 2rem;
      }

      .support-highlights div {
        padding: 1rem;
        border-radius: var(--radius-md);
        background: #f8fafc;
        border: 1px solid var(--panel-muted);
      }

      .support-highlights strong {
        display: block;
        margin-bottom: 0.35rem;
        font-size: 1rem;
      }

      .support-highlights span {
        color: var(--text-muted);
        font-size: 0.95rem;
        line-height: 1.5;
      }

      .form-card {
        padding: 2rem;
      }

      .form-card h2 {
        margin: 0 0 0.5rem;
        font-size: 1.5rem;
      }

      .form-card > p {
        margin: 0 0 1.5rem;
        color: var(--text-muted);
        line-height: 1.6;
      }

      .status-banner {
        margin-bottom: 1rem;
        padding: 0.9rem 1rem;
        border-radius: 14px;
        font-weight: 600;
      }

      .status-banner.success {
        background: var(--success-bg);
        color: var(--success-text);
      }

      .status-banner.error {
        background: #fef3f2;
        color: var(--danger);
      }

      form {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        display: grid;
        gap: 0.5rem;
      }

      .field-header {
        display: flex;
        justify-content: space-between;
        align-items: baseline;
        gap: 0.75rem;
        flex-wrap: wrap;
      }

      label {
        font-weight: 700;
      }

      .field-meta {
        color: var(--text-muted);
        font-size: 0.9rem;
      }

      .required-mark {
        color: var(--danger);
      }

      input {
        width: 100%;
        padding: 0.95rem 1rem;
        border: 1px solid #b7c4d3;
        border-radius: 14px;
        background: #fff;
        color: var(--text-main);
        font: inherit;
        transition: border-color 0.2s ease, box-shadow 0.2s ease;
      }

      input::placeholder {
        color: #6b7b90;
      }

      input:focus {
        outline: 2px solid transparent;
        border-color: var(--primary);
        box-shadow: 0 0 0 4px #dbe8ff;
      }

      input[aria-invalid="true"] {
        border-color: var(--danger);
        box-shadow: 0 0 0 4px #fde2e0;
      }

      .helper-text,
      .error-text {
        font-size: 0.92rem;
        line-height: 1.5;
      }

      .helper-text {
        color: var(--text-muted);
      }

      .error-text {
        color: var(--danger);
        font-weight: 600;
      }

      .submit-button {
        margin-top: 0.5rem;
        border: 0;
        border-radius: 999px;
        padding: 1rem 1.25rem;
        background: linear-gradient(135deg, var(--primary) 0%, var(--primary-dark) 100%);
        color: #fff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
      }

      .submit-button:hover {
        filter: brightness(1.05);
      }

      .submit-button:focus-visible {
        outline: 2px solid transparent;
        box-shadow: 0 0 0 4px #dbe8ff;
      }

      .privacy-note {
        margin: 0.75rem 0 0;
        color: var(--text-muted);
        font-size: 0.9rem;
      }

      @media (max-width: 900px) {
        .hero-card {
          grid-template-columns: 1fr;
        }

        .support-highlights {
          grid-template-columns: 1fr;
        }

        .hero-copy,
        .form-card {
          padding: 1.5rem;
        }
      }

      @media (forced-colors: active) {
        body,
        .hero-copy,
        .form-card,
        .support-highlights div,
        input {
          background: Canvas;
          color: CanvasText;
          border-color: ButtonBorder;
          box-shadow: none;
        }

        .skip-link,
        .submit-button {
          background: ButtonFace;
          color: ButtonText;
          border: 1px solid ButtonBorder;
        }

        .status-banner.success,
        .status-banner.error,
        .eyebrow {
          background: Canvas;
          color: CanvasText;
          border: 1px solid ButtonBorder;
        }

        input:focus,
        .submit-button:focus-visible {
          outline: 2px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <div id="app"></div>
    <script>
      const app = document.getElementById("app");

      const initialState = {
        values: {
          fullName: "",
          email: "",
          phone: ""
        },
        errors: {},
        touched: {},
        status: { type: "", message: "" }
      };

      let state = structuredClone(initialState);

      function validate(values) {
        const errors = {};

        if (!values.fullName.trim()) {
          errors.fullName = "Enter your full name.";
        }

        if (!values.email.trim()) {
          errors.email = "Enter your email address.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(values.email.trim())) {
          errors.email = "Enter a valid email address.";
        }

        if (values.phone.trim() && !/^\+?[0-9()\-\s]{7,20}$/.test(values.phone.trim())) {
          errors.phone = "Use digits, spaces, parentheses, or dashes only.";
        }

        return errors;
      }

      function FormField({
        id,
        label,
        type = "text",
        placeholder,
        required = false,
        value,
        helperText,
        error,
        metaText = required ? "Required" : "Optional"
      }) {
        const helperId = helperText ? `${id}-helper` : "";
        const errorId = error ? `${id}-error` : "";
        const describedBy = [helperId, errorId].filter(Boolean).join(" ") || null;

        return `
          <div class="form-field">
            <div class="field-header">
              <label for="${id}">
                ${label}${required ? ' <span class="required-mark" aria-hidden="true">*</span>' : ""}
              </label>
              <span class="field-meta">${metaText}</span>
            </div>
            <input
              id="${id}"
              name="${id}"
              type="${type}"
              value="${escapeHtml(value)}"
              placeholder="${placeholder}"
              ${required ? 'required aria-required="true"' : ""}
              ${error ? 'aria-invalid="true"' : ""}
              ${describedBy ? `aria-describedby="${describedBy}"` : ""}
              autocomplete="${id === "fullName" ? "name" : id === "email" ? "email" : "tel"}"
            />
            ${helperText ? `<p class="helper-text" id="${helperId}">${helperText}</p>` : ""}
            ${error ? `<p class="error-text" id="${errorId}">${error}</p>` : ""}
          </div>
        `;
      }

      function ContactForm() {
        const errors = state.errors;

        return `
          <section class="form-card" aria-labelledby="contact-form-heading">
            <h2 id="contact-form-heading">Send a support request</h2>
            <p>Tell us what you need and our team will follow up with the right next step.</p>
            ${state.status.message ? `<div class="status-banner ${state.status.type}" aria-live="polite">${state.status.message}</div>` : ""}
            <form id="support-form" novalidate>
              ${FormField({
                id: "fullName",
                label: "Full name",
                placeholder: "Taylor Morgan",
                required: true,
                value: state.values.fullName,
                error: errors.fullName
              })}
              ${FormField({
                id: "email",
                label: "Email address",
                type: "email",
                placeholder: "taylor@example.com",
                required: true,
                value: state.values.email,
                error: errors.email
              })}
              ${FormField({
                id: "phone",
                label: "Phone number",
                type: "tel",
                placeholder: "+1 (555) 123-4567",
                required: false,
                value: state.values.phone,
                helperText: "Optional. Use a format like +1 (555) 123-4567 so we can call you back if needed.",
                error: errors.phone
              })}
              <button class="submit-button" type="submit">Submit request</button>
            </form>
            <p class="privacy-note">We use this information only to respond to your support request.</p>
          </section>
        `;
      }

      function SupportHero() {
        return `
          <section class="hero-copy" aria-labelledby="support-page-title">
            <div>
              <span class="eyebrow">Support</span>
              <h1 id="support-page-title">Talk to our team when something needs attention.</h1>
              <p>
                Reach product specialists for account help, technical questions, and urgent support
                needs through one clean intake form.
              </p>
            </div>
            <div class="support-highlights" aria-label="Support highlights">
              <div>
                <strong>Fast routing</strong>
                <span>Your request lands with the team best equipped to help.</span>
              </div>
              <div>
                <strong>Clear follow-up</strong>
                <span>We respond using the contact details you provide here.</span>
              </div>
              <div>
                <strong>Built for urgency</strong>
                <span>Add a phone number if you want us to reach out faster.</span>
              </div>
            </div>
          </section>
        `;
      }

      function SupportPage() {
        return `
          <header class="page-shell">
            <main id="main-content" tabindex="-1">
              <div class="hero-card">
                ${SupportHero()}
                ${ContactForm()}
              </div>
            </main>
          </header>
        `;
      }

      function escapeHtml(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll('"', "&quot;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;");
      }

      function render() {
        app.innerHTML = SupportPage();

        const form = document.getElementById("support-form");
        const fields = form.querySelectorAll("input");

        fields.forEach((field) => {
          field.addEventListener("input", handleInput);
          field.addEventListener("blur", handleBlur);
        });

        form.addEventListener("submit", handleSubmit);
      }

      function updateState(nextState) {
        state = { ...state, ...nextState };
        render();
      }

      function handleInput(event) {
        const { name, value } = event.target;
        const nextValues = { ...state.values, [name]: value };
        const nextErrors = { ...state.errors };

        if (state.touched[name]) {
          const validated = validate(nextValues);
          if (validated[name]) {
            nextErrors[name] = validated[name];
          } else {
            delete nextErrors[name];
          }
        }

        updateState({
          values: nextValues,
          errors: nextErrors,
          status: state.status.type === "success" ? { type: "", message: "" } : state.status
        });
      }

      function handleBlur(event) {
        const { name } = event.target;
        const nextTouched = { ...state.touched, [name]: true };
        const validated = validate(state.values);
        updateState({
          touched: nextTouched,
          errors: {
            ...state.errors,
            ...(validated[name] ? { [name]: validated[name] } : {})
          }
        });
      }

      function handleSubmit(event) {
        event.preventDefault();

        const nextTouched = {
          fullName: true,
          email: true,
          phone: true
        };
        const errors = validate(state.values);

        if (Object.keys(errors).length > 0) {
          state = {
            ...state,
            touched: nextTouched,
            errors,
            status: {
              type: "error",
              message: "Check the highlighted fields and try again."
            }
          };
          render();

          const firstInvalid = document.querySelector('[aria-invalid="true"]');
          if (firstInvalid) {
            firstInvalid.focus();
          }
          return;
        }

        updateState({
          values: { fullName: "", email: "", phone: "" },
          errors: {},
          touched: {},
          status: {
            type: "success",
            message: "Your support request has been submitted. We’ll be in touch soon."
          }
        });
      }

      render();
    </script>
  </body>
</html>
