            ${error ? `<p class="error-text" id="${errorId}">${error}</p>` : ""}
          </div>
        `;
      }

      function ContactForm() {
        const errors = state.errors;

        return `
          <section class="form-card" aria-labelledby="contact-form-heading">
            <h2 id="contact-form-heading">Send a support request</h2>
            <p>Tell us what you need and our team will follow up with the right next step.</p>
            ${state.status.message ? `<div class="status-banner ${state.status.type}" aria-live="polite">${state.status.message}</div>` : ""}
            <form id="support-form" novalidate>
              ${FormField({
                id: "fullName",
                label: "Full name",
                placeholder: "Taylor Morgan",
                required: true,
                value: state.values.fullName,
                error: errors.fullName
              })}
              ${FormField({
                id: "email",
                label: "Email address",
                type: "email",
                placeholder: "taylor@example.com",
                required: true,
                value: state.values.email,
                error: errors.email
              })}
              ${FormField({
                id: "phone",
                label: "Phone number",
                type: "tel",
                placeholder: "+1 (555) 123-4567",
                required: false,
                value: state.values.phone,
                helperText: "Optional. Use a format like +1 (555) 123-4567 so we can call you back if needed.",
